def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    optimal_target = 0.5 * bins.max() if len(bins) > 0 else 0.5
    return np.where(remaining >= 0, np.exp(-((remaining - optimal_target) ** 2)), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    valid = remaining >= 0
    if not np.any(valid):
        return np.full_like(bins, -np.inf, dtype=float)
    target = np.median(bins[bins > 0]) if np.any(bins > 0) else 1.0
    scores = np.where(valid, 1.0 / (1.0 + np.abs(remaining - 0.5 * target) ** 3), -np.inf)
    return scores
